-- IDS X-Series X64 catalog (X-Series Installer Manual 700-398-02O, X-Series User Manual 700-398-01J).
-- Location 1-8 (Table 5-7), 23, 101-164 (Table 23), 197, 201-208 (Table 26); user program options 0-5 (User manual section 9).

INSERT INTO manufacturer (slug, name) VALUES ('ids', 'IDS');
INSERT INTO panel_family (manufacturer_id, slug, name, engine_key)
	SELECT id, 'ids-xseries', 'X-Series', $q$ids-xseries$q$ FROM manufacturer WHERE slug = 'ids';
INSERT INTO panel_model (family_id, slug, name, firmware, installer_code_default, master_code_default, source_doc)
	SELECT id, $q$x64$q$, $q$X64$q$, $q$2.8x$q$, $q$9999$q$, $q$1234$q$, $q$IDS X-Series Installer Manual 700-398-02O$q$
	FROM panel_family WHERE slug = 'ids-xseries';

INSERT INTO keypad_model (family_id, slug, name, component_key, description, display_type, light_count)
	SELECT id, $q$classic-led$q$, $q$Classic LED$q$, $q$ids-classic-led$q$, $q$16-zone LED keypad with READY, ARM, AWAY and POWER status lights (Installer manual Figure 3).$q$, $q$lights$q$, 16
	FROM panel_family WHERE slug = 'ids-xseries';
INSERT INTO panel_model_keypad (panel_model_id, keypad_model_id, is_default)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, true FROM keypad_model WHERE slug = $q$classic-led$q$;

INSERT INTO menu_group (panel_model_id, slug, label, position)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$zones$q$, $q$Zones$q$, 0);
INSERT INTO menu_group (panel_model_id, slug, label, position)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$partitions$q$, $q$Partitions$q$, 1);
INSERT INTO menu_group (panel_model_id, slug, label, position)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$codes$q$, $q$Codes$q$, 2);

INSERT INTO section (panel_model_id, group_id, slug, num, range_start, range_end, kind, label, description, sub_digits, rule, entries, options, subs, tips, related, pages, confirm, danger, verified, position)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, $q$zone-types$q$, NULL, 1, 8, $q$data$q$, $q$Zone types$q$, $q$Sets the type of each zone, 8 zones per location (Installer manual 700-398-02O, Location 1-8, pages 14-16, Tables 5-7). Location 1 is zones 1-8, location 2 is zones 9-16, up to location 8 for zones 57-64. Star-advance method: enter the location number followed by [*], then each press of [*] steps to the next zone; type a zone type and press [*] to set it (manual example: [2][*], [*], [*], [*], [4][*] changes zone 12 to Instant). Zones 1-8 are onboard. Zones 9-16 need the plug-in expander P/N 860-06-X-08PI (X16 and X64 only); zones 17-64 need expanders (X64 only). Zones 9-64 default to 00 (disabled) and must also be added to a partition in locations 201-208 before they are enabled. Defaults for zones 1-8: Table 6 and 7.$q$, NULL, $q${"kind":"block","start":1,"size":8,"base":0,"describe":"Zones {first}–{last}","entries":{"label":"Zone {item} type","digits":2,"def":"00","lookup":"zoneTypes","defByItem":{"1":"01","2":"02","3":"04","4":"04","5":"04","6":"04","7":"04","8":"04"}}}$q$::jsonb, NULL, NULL, NULL, $q$["Valid zone types: 00-05, 08, 10-15 (Installer manual, under Table 7); 09 is listed in Table 5 as new (newer firmware only).","If you need a panic zone that can be viewed on a keypad, do not use the dedicated panic input (Installer manual, Location 1-8 note)."]$q$::jsonb, $q$[]$q$::jsonb, 1, false, false, true, 0
	FROM menu_group WHERE panel_model_id = (SELECT id FROM panel_model WHERE slug = 'x64') AND slug = $q$zones$q$;
INSERT INTO section (panel_model_id, group_id, slug, num, range_start, range_end, kind, label, description, sub_digits, rule, entries, options, subs, tips, related, pages, confirm, danger, verified, position)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, $q$zone-properties$q$, NULL, 101, 164, $q$toggle$q$, $q$Zone properties$q$, $q$Properties of one zone; location 100 + zone number, so zone 9 is location 109 (Installer manual 700-398-02O, Locations 101-164, page 25-26, Table 23). Each location is a bitmap of 16 properties, one per LED (Table 23). Entering a bitmapped location (Installer manual, Programming a Bitmapped Location, page 13): READY goes solid and AWAY flashes; [#] exits the location. Only Zone bypassing (LED 6) is on by default. See section 14 of the User manual for stay profiles.$q$, NULL, $q${"kind":"offset","start":101,"base":1,"describe":"Zone {i} properties"}$q$::jsonb, NULL, $q$[{"n":1,"on":"Tamper by Zone","off":"—","def":false},{"n":2,"on":"Cross-zone","off":"—","def":false},{"n":3,"on":"Shutdown Zone","off":"—","def":false},{"n":4,"on":"Silent Zone","off":"—","def":false},{"n":5,"on":"Chime Zone","off":"—","def":false},{"n":6,"on":"Zone bypassing","off":"—","def":true},{"n":7,"on":"Zone always triggers PGM","off":"—","def":false},{"n":8,"on":"Reserved","off":"—","def":false},{"n":9,"on":"Stay Profile 1","off":"—","def":false},{"n":10,"on":"Stay Profile 2","off":"—","def":false},{"n":11,"on":"Stay Profile 3","off":"—","def":false},{"n":12,"on":"Stay Profile 4","off":"—","def":false},{"n":13,"on":"Buzz Profile 1","off":"—","def":false},{"n":14,"on":"Buzz Profile 2","off":"—","def":false},{"n":15,"on":"Buzz Profile 3","off":"—","def":false},{"n":16,"on":"Buzz Profile 4","off":"—","def":false}]$q$::jsonb, NULL, $q$["LED 8 is Reserved in Table 23.","Entry/Exit zones cannot be cross-zones (Installer manual, Cross-zoning)."]$q$::jsonb, $q$[]$q$::jsonb, 1, false, false, true, 0
	FROM menu_group WHERE panel_model_id = (SELECT id FROM panel_model WHERE slug = 'x64') AND slug = $q$zones$q$;
INSERT INTO section (panel_model_id, group_id, slug, num, range_start, range_end, kind, label, description, sub_digits, rule, entries, options, subs, tips, related, pages, confirm, danger, verified, position)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, $q$partition-zones$q$, NULL, 201, 208, $q$toggle$q$, $q$Partition zone allocation$q$, $q$Allocates zones to partition 1-8 (location 200 + partition number); lit zone LEDs are the zones in the partition (Installer manual 700-398-02O, Locations 201-208, page 29, Table 26). The 64 zones are shown as 4 pages of 16 zones; press [*] to go to the next page. The page lights READY (zones 1-16), ARM (17-32), AWAY (33-48) and POWER (49-64) mark the current page (Table 26, Figures 3 and 4). A zone may belong to more than one partition. The keypad start zone in location 241 is needed for keypads displaying zones higher than 16. The factory default is not given in the manual (all zones are shown as off here); check the real panel.$q$, NULL, $q${"kind":"offset","start":201,"base":1,"describe":"Partition {i} zones","options":{"count":64,"on":"Zone {k}","off":"—","def":false}}$q$::jsonb, NULL, NULL, NULL, $q$["Zones 9-64 only work once their type is set (locations 2-8) and they are allocated to a partition here."]$q$::jsonb, $q$[]$q$::jsonb, 4, false, false, false, 0
	FROM menu_group WHERE panel_model_id = (SELECT id FROM panel_model WHERE slug = 'x64') AND slug = $q$partitions$q$;
INSERT INTO section (panel_model_id, group_id, slug, num, range_start, range_end, kind, label, description, sub_digits, rule, entries, options, subs, tips, related, pages, confirm, danger, verified, position)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, $q$code-length$q$, 23, NULL, NULL, $q$data$q$, $q$Code length$q$, $q$Number of digits in user, installer and maintenance codes: 4 or 6 (Installer manual 700-398-02O, Location 23, Table 12). Default 4. Does not affect the download code (always 4 digits). Changing from 6 to 4 resets all user codes to their defaults.$q$, NULL, NULL, $q$[{"label":"Code length (4 or 6)","digits":1,"def":"4"}]$q$::jsonb, NULL, NULL, $q$[]$q$::jsonb, $q$[]$q$::jsonb, 1, false, false, true, 0
	FROM menu_group WHERE panel_model_id = (SELECT id FROM panel_model WHERE slug = 'x64') AND slug = $q$codes$q$;
INSERT INTO section (panel_model_id, group_id, slug, num, range_start, range_end, kind, label, description, sub_digits, rule, entries, options, subs, tips, related, pages, confirm, danger, verified, position)
	SELECT (SELECT id FROM panel_model WHERE slug = 'x64'), id, $q$installer-code$q$, 197, NULL, NULL, $q$data$q$, $q$Installer code$q$, $q$The code used to enter installer programming (Installer manual 700-398-02O, Location 197). Default 9999 (999999 with 6-digit codes, Table 12). Length is set in location 23.$q$, NULL, NULL, $q$[{"label":"Installer code","digits":4,"def":"9999"}]$q$::jsonb, NULL, NULL, $q$[]$q$::jsonb, $q$[]$q$::jsonb, 1, false, false, true, 1
	FROM menu_group WHERE panel_model_id = (SELECT id FROM panel_model WHERE slug = 'x64') AND slug = $q$codes$q$;

INSERT INTO lookup (panel_model_id, key, values)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$zoneTypes$q$, $q${"title":"Zone types","values":{"00":"Disabled","01":"Primary entry/exit","02":"Follower","03":"Panic/priority","04":"Instant","05":"Arm/disarm","08":"Secondary entry/exit","09":"Instant fire (newer firmware only)","10":"Fire","11":"Tamper","12":"24 hour alarm","13":"Warning","14":"Push to arm","15":"Outdoor instant"}}$q$::jsonb);

INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u0$q$, $q$hold * [master] * [0] * [new code] *$q$, $q$Add a new user code$q$, 'command', $q$Option 0. The code goes in the first free slot. READY and ARM flash simultaneously once inside option 0 (ARM and READY only alternate while waiting for the master code); type each new code followed by [*]; [#] leaves the option. X-Series User manual 700-398-01J, section 9$q$, 0, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u1$q$, $q$hold * [master] * [1] * [old code] * [new code] *$q$, $q$Edit a user code$q$, 'command', $q$Option 1. READY and ARM flash after [1][*]; after the old code READY and AWAY flash with ARM on; after the new code READY and ARM flash again. X-Series User manual 700-398-01J, section 9$q$, 1, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u2$q$, $q$hold * [master] * [2] * [code] *$q$, $q$Delete a code (code known)$q$, 'command', $q$Option 2. READY and ARM flash; deleting the code in slot 1 resets it to 1234. X-Series User manual 700-398-01J, section 9$q$, 2, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u3$q$, $q$hold * [master] * [3] * [slot] * [code] *$q$, $q$Add or edit by slot$q$, 'command', $q$Option 3. READY and ARM flash; after the slot READY and AWAY flash with ARM on; after the code READY and ARM flash. Slots are 1-128. X-Series User manual 700-398-01J, section 9$q$, 3, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u4$q$, $q$hold * [master] * [4] * [slot] *$q$, $q$Delete by slot$q$, 'command', $q$Option 4. READY and ARM flash. Use option 5 to find a code's slot. X-Series User manual 700-398-01J, section 9$q$, 4, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);
INSERT INTO keypad_command (panel_model_id, slug, keys, label, kind, description, position, payload)
	VALUES ((SELECT id FROM panel_model WHERE slug = 'x64'), $q$u5$q$, $q$hold * [master] * [5] * [code] *$q$, $q$View a code's slot$q$, 'command', $q$Option 5. READY and ARM flash; the slot number is shown on the zone LEDs (User manual Table 2). X-Series User manual 700-398-01J, section 9$q$, 5, $q${"tips":["Enter user program mode first: hold [*] until the beep, then [master code] [*] (ARM and READY alternate, then READY flashes). Press [#] to leave the option, [#] again to exit."]}$q$::jsonb);

